/// <summary>
/// Extension of table GUPPricingRuleExclusionCopy
/// </summary>
[ExtensionOf(tableStr(GUPPricingRuleExclusionCopy))]
final class METGUPPricingRuleExclusionCopyTable_Extension
{
}

Method.Source:
/// <summary>
/// does the record exist?
/// </summary>
/// <param name = "_exclusion">exclusion</param>
/// <param name = "_ruleId">rule id</param>
/// <returns>result</returns>
static boolean metExist(GUPExclusion _exclusion, RefRecId _ruleId)
{
    return _exclusion && _ruleId
    && (select firstOnly RecId
        from GUPPricingRuleExclusionCopy
        where GUPPricingRuleExclusionCopy.exclusion == _exclusion
        &&    GUPPricingRuleExclusionCopy.ruleId    == _ruleId  ).RecId != 0;
}
